actions.script:
import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
def ds = ec.l10n.parseTimestamp(fromD + ' 00:00:00', 'yyyy-MM-dd HH:mm:ss')
def de = ec.l10n.parseTimestamp(thruD + ' 23:59:59.999', 'yyyy-MM-dd HH:mm:ss.SSS')
def paymentReport=ec.service.sync().name('zenith.pos.PosServices.get#PosPaymentBreakdown').parameters([fromDate:ds,thruDate:de]).call()
def methodMap=[:]
(paymentReport.rows ?: []).each { m -> methodMap[m.paymentMethod]=[m:m.paymentMethod,amt:m.totalAmount,cnt:m.transactionCount] }
def total=paymentReport.totalAmount ?: BigDecimal.ZERO
def rows = methodMap.values().sort { -(it.amt as BigDecimal) }
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) rows = rows.findAll { (it.m ?: '').toLowerCase().contains(stx) }
def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def num = { v -> String.format("%.2f", (v ?: 0.0) as double) }
StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - Payment Wise Report\n")
csv.append("Period: ${fromD} to ${thruD}  |  Generated: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
csv.append("Payment Method,Amount,Transactions,Share %\n")
rows.each { r ->
    def pct = total > 0 ? (r.amt * 100 / total) : 0.0G
    csv.append("${esc(r.m)},${num(r.amt)},${r.cnt},${String.format('%.2f', pct as double)}\n")
}
ec.web.sendTextResponse(csv.toString(), "text/csv", "Payment_Wise_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv")
